class Reader {
  final List<int> data;
  int position;
  Reader(this.data, [this.position = 0]);
  int byte() => data[position++];
  List<int> take(int n) {
    final v = data.sublist(position, position + n);
    position += n;
    return v;
  }

  int uleb() {
    var value = 0, shift = 0;
    while (true) {
      final b = byte();
      value |= (b & 127) << shift;
      if (b < 128) return value;
      shift += 7;
    }
  }

  int zigzag() {
    final v = uleb();
    return v % 2 == 0 ? v ~/ 2 : -(v + 1) ~/ 2;
  }

  int u32() {
    final a = take(4);
    return a[0] | (a[1] << 8) | (a[2] << 16) | (a[3] << 24);
  }
}

void appendULEB(List<int> out, int n) {
  while (n >= 128) {
    out.add(n % 128 + 128);
    n ~/= 128;
  }
  out.add(n);
}

void appendZigzag(List<int> out, int x) {
  appendULEB(out, x >= 0 ? 2 * x : -2 * x - 1);
}

void appendU32(List<int> out, int n) {
  for (var i = 0; i < 4; i++) {
    out.add((n >> (8 * i)) & 255);
  }
}

List<int> pack(List<int> a, int w) {
  final out = List.filled(a.length * w ~/ 8, 0);
  for (var i = 0; i < a.length; i++) {
    for (var j = 0; j < w; j++) {
      if (((a[i] >> j) & 1) != 0) {
        final k = i * w + j;
        out[k ~/ 8] |= 1 << (k % 8);
      }
    }
  }
  return out;
}

List<int> unpack(Reader r, int count, int w) {
  final data = r.take(count * w ~/ 8), out = List.filled(count, 0);
  for (var i = 0; i < count; i++) {
    for (var j = 0; j < w; j++) {
      final k = i * w + j;
      out[i] |= ((data[k ~/ 8] >> (k % 8)) & 1) << j;
    }
  }
  return out;
}

int adler(List<int> data) {
  var a = 1, b = 0;
  for (final v in data) {
    a = (a + v) % 65521;
    b = (b + a) % 65521;
  }
  return b * 65536 + a;
}

List<int> encodeHybrid(List<int> a, int w) {
  final out = <int>[];
  int run(int i) {
    var j = i + 1;
    while (j < a.length && a[j] == a[i]) {
      j++;
    }
    return j - i;
  }

  var i = 0;
  while (i < a.length) {
    final length = run(i);
    if (length >= 8) {
      appendULEB(out, 2 * length);
      for (var j = 0; j < (w + 7) ~/ 8; j++) {
        out.add((a[i] >> (8 * j)) & 255);
      }
      i += length;
    } else {
      var j = i, g = 0;
      do {
        j += 8;
        g++;
      } while (j < a.length && g < 63 && run(j) < 8);
      appendULEB(out, 2 * g + 1);
      final values = List.filled(8 * g, 0);
      values.setRange(0, min(j, a.length) - i, a.skip(i));
      out.addAll(pack(values, w));
      i = j;
    }
  }
  return out;
}

List<int> decodeHybrid(Reader r, int count, int w) {
  final out = <int>[];
  while (out.length < count) {
    final header = r.uleb();
    if (header % 2 == 0) {
      var value = 0;
      for (var j = 0; j < (w + 7) ~/ 8; j++) {
        value |= r.byte() << (8 * j);
      }
      out.addAll(List.filled(header ~/ 2, value));
    } else {
      out.addAll(unpack(r, 8 * ((header - 1) ~/ 2), w));
    }
  }
  return out.sublist(0, count);
}

part of 'main.dart';

const methodNames = [
  'PLAIN',
  'DICTIONARY',
  'RLE',
  'DELTA_BINARY_PACKED',
  'DELTA_LENGTH_BYTE_ARRAY',
];
List<int> candidates(String kind) => switch (kind) {
  'BOOL' => [0, 2],
  'STRING' => [0, 1, 4],
  _ => [0, 1, 3],
};
List<int> encodeDelta(List<int> a) {
  final out = <int>[];
  appendULEB(out, 128);
  appendULEB(out, 4);
  appendULEB(out, a.length);
  appendZigzag(out, a.isEmpty ? 0 : a[0]);
  for (var start = 1; start < a.length; start += 128) {
    final end = min(start + 128, a.length),
        deltas = [for (var i = start; i < end; i++) a[i] - a[i - 1]],
        minimum = deltas.reduce(min);
    appendZigzag(out, minimum);
    final widths = <int>[];
    for (var t = 0; t < 4; t++) {
      var maximum = 0;
      for (var i = t * 32; i < min((t + 1) * 32, deltas.length); i++) {
        maximum = max(maximum, deltas[i] - minimum);
      }
      widths.add(maximum.bitLength);
      out.add(maximum.bitLength);
    }
    for (var t = 0; t < 4 && t * 32 < deltas.length; t++) {
      final values = List.filled(32, 0);
      for (var i = t * 32; i < min((t + 1) * 32, deltas.length); i++) {
        values[i - t * 32] = deltas[i] - minimum;
      }
      out.addAll(pack(values, widths[t]));
    }
  }
  return out;
}

List<int> decodeDelta(Reader r) {
  r.uleb();
  r.uleb();
  final n = r.uleb(), first = r.zigzag();
  if (n == 0) return [];
  final out = [first];
  while (out.length < n) {
    final minimum = r.zigzag(), widths = r.take(4);
    for (var t = 0; t < 4 && out.length < n; t++) {
      final values = unpack(r, 32, widths[t]), count = min(32, n - out.length);
      for (final v in values.take(count)) {
        out.add(out.last + minimum + v);
      }
    }
  }
  return out;
}

String dictionaryKey(Value v, String kind) =>
    kind == 'STRING' ? v.text : '${v.number}';
List<int> encodeValues(
  List<Value> a,
  String kind,
  int method,
  List<Value> dictionary,
) {
  final out = <int>[];
  switch (method) {
    case 0:
      if (kind == 'BOOL') {
        final values = List.filled((a.length + 7) ~/ 8 * 8, 0);
        for (var i = 0; i < a.length; i++) {
          values[i] = a[i].number;
        }
        return pack(values, 1);
      }
      for (final v in a) {
        if (kind == 'STRING') {
          appendU32(out, v.text.length);
          out.addAll(v.text.codeUnits);
        } else {
          appendU32(out, v.number);
        }
      }
      break;
    case 1:
      final w = max(0, dictionary.length - 1).bitLength,
          indices = {
            for (var i = 0; i < dictionary.length; i++)
              dictionaryKey(dictionary[i], kind): i,
          };
      out.add(w);
      out.addAll(
        encodeHybrid([for (final v in a) indices[dictionaryKey(v, kind)]!], w),
      );
      break;
    case 2:
      final data = encodeHybrid([for (final v in a) v.number], 1);
      appendU32(out, data.length);
      out.addAll(data);
      break;
    case 3:
      out.addAll(encodeDelta([for (final v in a) v.number]));
      break;
    case 4:
      out.addAll(encodeDelta([for (final v in a) v.text.length]));
      for (final v in a) {
        out.addAll(v.text.codeUnits);
      }
      break;
  }
  return out;
}

List<Value> decodeValues(
  Reader r,
  int count,
  String kind,
  int method,
  List<Value> dictionary,
) {
  switch (method) {
    case 0:
      if (kind == 'BOOL')
        return [
          for (final n in unpack(r, (count + 7) ~/ 8 * 8, 1).take(count))
            Value(number: n),
        ];
      final out = <Value>[];
      for (var i = 0; i < count; i++) {
        if (kind == 'STRING') {
          out.add(Value(text: String.fromCharCodes(r.take(r.u32()))));
        } else {
          var n = r.u32();
          if (n >= 1 << 31) n -= 1 << 32;
          out.add(Value(number: n));
        }
      }
      return out;
    case 1:
      final w = r.byte();
      return [for (final index in decodeHybrid(r, count, w)) dictionary[index]];
    case 2:
      final reader = Reader(r.take(r.u32()));
      return [for (final v in decodeHybrid(reader, count, 1)) Value(number: v)];
    case 3:
      return [for (final v in decodeDelta(r)) Value(number: v)];
    default:
      return [
        for (final n in decodeDelta(r))
          Value(text: String.fromCharCodes(r.take(n))),
      ];
  }
}

void writeStatValue(List<int> out, Value v, String kind) {
  switch (kind) {
    case 'STRING':
      appendULEB(out, v.text.length);
      out.addAll(v.text.codeUnits);
      break;
    case 'BOOL':
      out.add(v.number);
      break;
    default:
      appendZigzag(out, v.number);
  }
}

Value readStatValue(Reader r, String kind) => switch (kind) {
  'STRING' => Value(text: String.fromCharCodes(r.take(r.uleb()))),
  'BOOL' => Value(number: r.byte()),
  _ => Value(number: r.zigzag()),
};

import 'dart:io';
import 'dart:math';
